async function load_gate_pass_receipt(pass) {
    const {message: receipt} = await frappe.call({
        method: "frappe.model.mapper.make_mapped_doc",
        args: {method: "erpnext.buying.doctype.purchase_order.purchase_order.make_purchase_receipt", source_name: pass.purchase_order},
        freeze: true,
        freeze_message: __("Preparing Goods Receipt Note…"),
    });
    if (!receipt?.items?.length) {
        frappe.msgprint(__("This purchase order has no items pending receipt."));
        return;
    }
    const arrivals = new Map((pass.items || []).map(row => [row.purchase_order_item, flt(row.arrived_qty)]));
    if (arrivals.size) {
        receipt.items = receipt.items.filter(row => arrivals.get(row.purchase_order_item) > 0);
        if (!receipt.items.length) {
            frappe.msgprint(__("The items on this gate pass have no quantities pending receipt."));
            return;
        }
        for (const row of receipt.items) {
            const quantity = Math.min(flt(row.qty), arrivals.get(row.purchase_order_item));
            row.qty = row.received_qty = quantity;
            row.stock_qty = quantity * flt(row.conversion_factor);
        }
    }
    receipt.inward_gate_pass = pass.name;
    receipt.station = pass.station;
    if (pass.delivery_note_no) receipt.supplier_delivery_note = pass.delivery_note_no;
    for (const row of receipt.items) row.station = pass.station;
    const [mapped] = frappe.model.sync(receipt);
    frappe.set_route("Form", mapped.doctype, mapped.name);
}

frappe.ui.form.on("Inward Gate Pass", {
    setup(frm) {
        frm.set_query("purchase_order", () => ({filters: {
            docstatus: 1,
            status: ["not in", ["Closed", "Completed", "On Hold"]],
            per_received: ["<", 100],
        }}));
        frm.set_query("station", () => ({filters: {company: frm.doc.company}}));
    },
    async purchase_order(frm) {
        if (!frm.doc.purchase_order) {
            await frm.set_value({company: null, supplier: null, station: null});
            return;
        }
        const orderName = frm.doc.purchase_order;
        const {message: order} = await frappe.db.get_value("Purchase Order", orderName,
            ["company", "supplier", "station"]);
        if (order && orderName === frm.doc.purchase_order) {
            await frm.set_value({company: order.company, supplier: order.supplier, station: order.station || null});
        }
    },
    refresh(frm) {
        if (frm.doc.docstatus !== 1) return;
        frm.add_custom_button(__("Goods Receipt Note (GRN)"), () => load_gate_pass_receipt(frm.doc), __("Create"));
        frm.add_custom_button(__("Goods Receipt Notes"), () => {
            frappe.route_options = {inward_gate_pass: frm.doc.name};
            frappe.set_route("List", "Purchase Receipt");
        }, __("View"));
    },
});

async function load_gate_arrival_items(frm, refresh = false) {
    const order = frm.doc.purchase_order;
    if (!frm.is_new() || (refresh && (frm.doc.items || []).length)) return;
    const token = Symbol();
    frm.gate_arrival_request = token;
    frm.clear_table("items");
    frm.refresh_field("items");
    if (!order) return;
    const {message: receipt} = await frappe.call({
        method: "frappe.model.mapper.make_mapped_doc",
        args: {method: "erpnext.buying.doctype.purchase_order.purchase_order.make_purchase_receipt", source_name: order},
    });
    if (frm.gate_arrival_request !== token || frm.doc.purchase_order !== order) return;
    for (const row of receipt?.items || []) {
        frm.add_child("items", {
            purchase_order_item: row.purchase_order_item, item_code: row.item_code, item_name: row.item_name,
            description: frappe.utils.html2text(row.description || ""), warehouse: row.warehouse,
            cost_center: row.cost_center, uom: row.uom, pending_qty: row.qty, arrived_qty: row.qty,
            rate: row.rate, currency: receipt.currency,
        });
    }
    frm.refresh_field("items");
}
frappe.ui.form.on("Inward Gate Pass", {
    refresh: frm => load_gate_arrival_items(frm, true),
    purchase_order: frm => load_gate_arrival_items(frm),
    validate(frm) {
        if (!frm.is_new() && !(frm.doc.items || []).length) return;
        const rows = frm.doc.items || [];
        if (!rows.some(row => flt(row.arrived_qty) > 0)) {
            frappe.throw(__("Enter an arrived quantity for at least one item."));
        }
        if (rows.some(row => flt(row.arrived_qty) < 0 || flt(row.arrived_qty) > flt(row.pending_qty))) {
            frappe.throw(__("Arrived quantity must be between zero and the pending quantity."));
        }
    },
});

async function show_gate_pass_order(frm) {
    const wrapper = frm.fields_dict.purchase_order_details.$wrapper;
    const orderName = frm.doc.purchase_order;
    const request = Symbol();
    frm.gate_pass_order_request = request;
    wrapper.empty();
    if (!orderName) return;
    wrapper.text(__("Loading purchase order details…"));

    let order;
    try {
        ({message: order} = await frappe.call({
            method: "frappe.client.get",
            args: {doctype: "Purchase Order", name: orderName},
        }));
    } catch {
        if (frm.gate_pass_order_request === request) {
            wrapper.text(__("Purchase order details could not be loaded."));
        }
        return;
    }
    if (frm.gate_pass_order_request !== request || frm.doc.purchase_order !== orderName) return;
    if (!order) {
        wrapper.text(__("Purchase order details are unavailable."));
        return;
    }

    const safe = value => frappe.utils.escape_html(String(value ?? ""));
    const money = value => format_currency(value, order.currency);
    const number = new Intl.NumberFormat(undefined, {maximumFractionDigits: 9});
    const qty = value => number.format(flt(value));
    const date = value => value ? frappe.datetime.str_to_user(value) : "";
    const table = (headers, rows) => `
        <div class="table-responsive">
            <table class="table table-bordered table-sm">
                <thead><tr>${headers.map(label => `<th scope="col">${safe(__(label))}</th>`).join("")}</tr></thead>
                <tbody>${rows.map(row => `<tr>${row.map(value => `<td>${safe(value)}</td>`).join("")}</tr>`).join("")}</tbody>
            </table>
        </div>`;
    const items = (order.items || []).map(row => [
        row.item_code, row.item_name, frappe.utils.html2text(row.description || ""),
        date(row.schedule_date), row.warehouse, row.uom, row.stock_uom, qty(row.conversion_factor),
        qty(row.qty), qty(row.received_qty), qty(Math.max(0, flt(row.qty) - flt(row.received_qty))),
        money(row.price_list_rate), qty(row.discount_percentage), money(row.rate), money(row.amount),
        money(row.net_rate), money(row.net_amount),
    ]);
    const taxes = (order.taxes || []).map(row => [
        row.description, row.account_head, row.charge_type, qty(row.rate), money(row.tax_amount),
    ]);
    const summary = [
        ["Currency", order.currency], ["Price List", order.buying_price_list],
        ["Order Date", date(order.transaction_date)], ["Required By", date(order.schedule_date)],
        ["Total Quantity", qty(order.total_qty)], ["Items Total", money(order.total)],
        ["Additional Discount", money(order.discount_amount)], ["Net Total", money(order.net_total)],
        ["Taxes and Charges", money(order.total_taxes_and_charges)], ["Grand Total", money(order.grand_total)],
    ];
    if (!order.disable_rounded_total) summary.push(["Rounded Total", money(order.rounded_total)]);

    wrapper.html(`
        <section class="mb-4">
            <h5>${safe(__("Purchase Order Details"))}</h5>
            <p class="text-muted">${safe(__("Quantities and prices from the linked purchase order."))}</p>
            ${table(["Item Code", "Item Name", "Description", "Required By", "Warehouse", "UOM",
                "Stock UOM", "Conversion Factor", "Ordered Qty", "Received Qty", "Pending Qty",
                "Price List Rate", "Discount %", "Rate", "Amount", "Net Rate", "Net Amount"], items)}
            <dl class="row mb-3">${summary.map(([label, value]) =>
                `<dt class="col-sm-3">${safe(__(label))}</dt><dd class="col-sm-3">${safe(value)}</dd>`).join("")}</dl>
            ${taxes.length ? `<h6>${safe(__("Taxes and Charges"))}</h6>
                ${table(["Description", "Account", "Charge Type", "Rate", "Tax Amount"], taxes)}` : ""}
        </section>`);
}

frappe.ui.form.on("Inward Gate Pass", {
    refresh: show_gate_pass_order,
    purchase_order: show_gate_pass_order,
});

function pick_buying_source(label, doctype, filters, load) {
    frappe.prompt({
        fieldtype: "Link", fieldname: "source", label: __(label), options: doctype,
        reqd: 1, get_query: () => ({filters: {docstatus: 1, ...filters}}),
    }, async ({source}) => {
        const {message: doc} = await frappe.call({
            method: "frappe.client.get", args: {doctype, name: source},
        });
        if (doc?.docstatus === 1) await load(doc);
    }, __(label), __("Load"));
}

async function load_buying_document(source, method, supplier) {
    const {message: doc} = await frappe.call({
        method,
        args: {source_name: source.name, ...(supplier ? {for_supplier: supplier} : {})},
        freeze: true,
        freeze_message: __("Loading items…"),
    });
    if (!doc?.items?.length) {
        frappe.msgprint(__("The selected document has no eligible items to load."));
        return;
    }
    if (source.station) doc.station = source.station;
    for (const row of doc.items) {
        if (!row.station && doc.station) row.station = doc.station;
    }
    const [mapped] = frappe.model.sync(doc);
    frappe.set_route("Form", mapped.doctype, mapped.name);
}

