frappe.ui.form.on("Purchase Receipt", {
    setup(frm) {
        frm.set_query("inward_gate_pass", () => ({filters: {
            docstatus: 1,
            company: frm.doc.company,
            supplier: frm.doc.supplier,
            ...(frm.doc.station ? {station: frm.doc.station} : {}),
        }}));
    },
    async inward_gate_pass(frm) {
        if (!frm.doc.inward_gate_pass) return;
        const {message: pass} = await frappe.db.get_value("Inward Gate Pass",
            frm.doc.inward_gate_pass, ["station", "delivery_note_no"]);
        if (pass) {
            await frm.set_value("station", pass.station);
            if (pass.delivery_note_no && !frm.doc.supplier_delivery_note) {
                await frm.set_value("supplier_delivery_note", pass.delivery_note_no);
            }
            for (const row of frm.doc.items || []) {
                await frappe.model.set_value(row.doctype, row.name, "station", pass.station);
            }
        }
    },
    async validate(frm) {
        if (!frm.doc.inward_gate_pass) return;
        const {message: pass} = await frappe.db.get_value("Inward Gate Pass", frm.doc.inward_gate_pass,
            ["docstatus", "company", "supplier", "station", "purchase_order"]);
        if (!pass || pass.docstatus !== 1 || pass.company !== frm.doc.company
            || pass.supplier !== frm.doc.supplier || pass.station !== frm.doc.station
            || frm.doc.items.some(row => row.purchase_order !== pass.purchase_order || row.station !== pass.station)) {
            frappe.throw(__("Use a submitted Inward Gate Pass for the same company, supplier, station, and purchase order as the receipt items."));
        }
    },
});

