        frm.add_custom_button(__("Load Request for Quotation"), () =>
            pick_buying_source("Load Request for Quotation", "Request for Quotation", {}, async source => {
                const suppliers = [...new Set((source.suppliers || []).map(row => row.supplier).filter(Boolean))];
                if (!suppliers.length) {
                    frappe.msgprint(__("The request has no invited suppliers."));
                    return;
