                frappe.prompt({
                    fieldtype: "Select", fieldname: "supplier", label: __("Supplier"),
                    options: ["", ...suppliers], reqd: 1,
                }, ({supplier}) => load(supplier), __("Choose Supplier"), __("Load"));
